macro_rules! deps {
    () => {
        AsyncRead!();
    };
}

macro_rules! AsyncBufRead {
    () => {
        deps!();
        # [doc = " Reads bytes asynchronously."] # [doc = ""] # [doc = " This trait is analogous to [`std::io::BufRead`], but integrates with"] # [doc = " the asynchronous task system. In particular, the [`poll_fill_buf`] method,"] # [doc = " unlike [`BufRead::fill_buf`], will automatically queue the current task for wakeup"] # [doc = " and return if data is not yet available, rather than blocking the calling"] # [doc = " thread."] # [doc = ""] # [doc = " Utilities for working with `AsyncBufRead` values are provided by"] # [doc = " [`AsyncBufReadExt`]."] # [doc = ""] # [doc = " [`std::io::BufRead`]: std::io::BufRead"] # [doc = " [`poll_fill_buf`]: AsyncBufRead::poll_fill_buf"] # [doc = " [`BufRead::fill_buf`]: std::io::BufRead::fill_buf"] # [doc = " [`AsyncBufReadExt`]: crate::io::AsyncBufReadExt"] pub trait AsyncBufRead : AsyncRead { # [doc = " Attempts to return the contents of the internal buffer, filling it with more data"] # [doc = " from the inner reader if it is empty."] # [doc = ""] # [doc = " On success, returns `Poll::Ready(Ok(buf))`."] # [doc = ""] # [doc = " If no data is available for reading, the method returns"] # [doc = " `Poll::Pending` and arranges for the current task (via"] # [doc = " `cx.waker().wake_by_ref()`) to receive a notification when the object becomes"] # [doc = " readable or is closed."] # [doc = ""] # [doc = " This function is a lower-level call. It needs to be paired with the"] # [doc = " [`consume`] method to function properly. When calling this"] # [doc = " method, none of the contents will be \"read\" in the sense that later"] # [doc = " calling [`poll_read`] may return the same contents. As such, [`consume`] must"] # [doc = " be called with the number of bytes that are consumed from this buffer to"] # [doc = " ensure that the bytes are never returned twice."] # [doc = ""] # [doc = " An empty buffer returned indicates that the stream has reached EOF."] # [doc = ""] # [doc = " [`poll_read`]: AsyncRead::poll_read"] # [doc = " [`consume`]: AsyncBufRead::consume"] fn poll_fill_buf (self : Pin < & mut Self > , cx : & mut Context < '_ >) -> Poll < io :: Result < & [u8] > > ; # [doc = " Tells this buffer that `amt` bytes have been consumed from the buffer,"] # [doc = " so they should no longer be returned in calls to [`poll_read`]."] # [doc = ""] # [doc = " This function is a lower-level call. It needs to be paired with the"] # [doc = " [`poll_fill_buf`] method to function properly. This function does"] # [doc = " not perform any I/O, it simply informs this object that some amount of"] # [doc = " its buffer, returned from [`poll_fill_buf`], has been consumed and should"] # [doc = " no longer be returned. As such, this function may do odd things if"] # [doc = " [`poll_fill_buf`] isn't called before calling it."] # [doc = ""] # [doc = " The `amt` must be `<=` the number of bytes in the buffer returned by"] # [doc = " [`poll_fill_buf`]."] # [doc = ""] # [doc = " [`poll_read`]: AsyncRead::poll_read"] # [doc = " [`poll_fill_buf`]: AsyncBufRead::poll_fill_buf"] fn consume (self : Pin < & mut Self > , amt : usize) ; }
    };
}

AsyncBufRead!();